      "query": {
        "en": "A long-form article / blog post — masthead, hero image placeholder, article body with figures and pull quotes, author byline, related posts. Use when the brief asks for \"blog\", \"article\", \"post\", \"essay\", or \"case study\".",
        "zh-CN": "使用这个插件完成以下任务：A long-form article / blog post — masthead, hero image placeholder, article body with figures and pull quotes, author byline, related posts. Use when the brief asks for \"blog\", \"article\", \"post\", \"essay\", or \"case study\"."
      },
      "exampleOutputs": [
        {
          "path": "./example.html",
          "title": "Blog Post"
        }
      ]
    },
    "context": {
      "skills": [
        {
